function gateTitle(key){const label=meta?.scenario?.gates?.find(g=>g.key===key)?.label;return gateTitles[key]||(key==='overBudget'?`Fiyat ${label||'bütçe üstü'}`:key==='underMinimumArea'?`Alan ${label||'alt sınırın altında'}`:label||key)}
const decisionLabel=f=>f?.decision==='shortlist'?'⭐ Kısa listede':f?.decision==='maybe'?'Belki':f?.decision==='excluded'?'İlgilenmiyorum':f?.note?'Not var':'';
const brief=(value,max=112)=>{const text=String(value||'').replace(/\s+/g,' ').trim();return text.length>max?text.slice(0,max-1).trim()+'…':text};
function criterion(c){const sub=brief(c.sub,120)||'Kaynak kayıtlı değil',aria=`${c.text}. ${sub}`;return `<span class="criterion state-${esc(c.state)}" role="group" aria-label="${esc(aria)}" title="${esc(aria)}"><span class="criterion-icon" aria-hidden="true">${esc(c.icon)}</span><span><b>${esc(c.text)}</b><small>${esc(sub)}</small></span></span>`}
function criteria(r,extra=''){return `<div class="criteria ${extra}" aria-label="Kritik doğrulamalar">${['parcel','road','natural','archaeological'].map(key=>criterion(criterionModel(r,key))).join('')}</div>`}
function routeCard(r){if(r.routeMax==null&&r.routeKmMax==null)return '<div class="route-main">Ölçüm bekliyor</div><small>Son-metre erişimi ayrıca incelenir</small>';const estimate=r.routeMax!=null&&r.evidence?.rota!=='verified',split=r.evidenceGrades?.route==='conflict'&&r.routeMin!=null&&r.routeMin<=45&&r.routeMax>45;const minutes=r.routeMax==null?'Süre yok':`${estimate?'≈':''}${r.routeMin!=null&&r.routeMin!==r.routeMax?num(r.routeMin)+'–':''}${num(r.routeMax)} dk`;const flag=split?'<span class="route-flag">45 dk eşiğinde belirsiz</span>':estimate?'<span class="route-flag">tahmini · doğrulanmadı</span>':'';const km=r.routeKmMax==null?'Mesafe kaydı yok':`${r.routeKmMin!=null&&r.routeKmMin!==r.routeKmMax?num(r.routeKmMin)+'–':''}${num(r.routeKmMax)} km`;return `<div class="route-main${estimate?' is-estimate':''}">${esc(minutes)}</div>${flag}<small>${esc(km)} · son-metre erişimi ayrı</small>`}
function miniParcel(r){const geometry=r.geometry;if(!geometry)return '<span class="parcel-mini-empty">Parsel sınırı<br>yok</span>';const rings=geometry.type==='Polygon'?geometry.coordinates:geometry.type==='MultiPolygon'?geometry.coordinates.flat():[];const points=rings.flat().filter(p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(p[0])&&Number.isFinite(p[1]));if(!points.length)return '<span class="parcel-mini-empty">Parsel sınırı<br>yok</span>';const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),k=Math.cos((ymin+ymax)/2*Math.PI/180)||1,scale=Math.min(72/((xmax-xmin)*k||1),52/(ymax-ymin||1));const path=rings.map(ring=>ring.filter(p=>Array.isArray(p)&&p.length>=2).map((p,i)=>`${i?'L':'M'}${(40+(p[0]-(xmin+xmax)/2)*k*scale).toFixed(1)},${(31-(p[1]-(ymin+ymax)/2)*scale).toFixed(1)}`).join(' ')+' Z').join(' ');return `<svg viewBox="0 0 80 62" aria-hidden="true"><path d="${path}" fill="#dfe9dd" fill-rule="evenodd" stroke="#25624e" stroke-width="1.5"/></svg>`}
function cardMedia(r){const first=r.photoEvidence?.items?.[0];return `<div class="listing-media">${first?.assetId?`<span class="listing-photo" data-photo-asset="${esc(first.assetId)}"><span>Fotoğraf yükleniyor</span></span>`:`<span class="listing-shape">${miniParcel(r)}</span>`}${first?.assetId?'<small>İlan fotoğrafı</small>':r.geometry?'<small>Parsel sınırı</small>':''}</div>`}
let photoObserver=null;
function hydratePhotos(root=document){
 const elements=[...root.querySelectorAll('[data-photo-asset]:not([data-photo-ready])')];
 if(!elements.length)return;
 const load=async el=>{el.dataset.photoReady='loading';try{const src=await getAsset(el.dataset.photoAsset),img=document.createElement('img');img.alt='Yetkili arşiv ilan fotoğrafı';img.loading='lazy';img.src=src;el.replaceChildren(img);el.dataset.photoReady='true'}catch{el.textContent='Fotoğraf yüklenemedi';el.dataset.photoReady='error'}};
 if(!('IntersectionObserver'in window)){elements.forEach(load);return}
 photoObserver??=new IntersectionObserver(entries=>entries.filter(e=>e.isIntersecting).forEach(e=>{photoObserver.unobserve(e.target);load(e.target)}),{rootMargin:'160px'});
 elements.forEach(el=>photoObserver.observe(el));
}
function loadScenario(){
 const fromUrl=scenarioFromUrl(meta);
 if(fromUrl)return fromUrl;
 try{return sanitizeScenario(JSON.parse(localStorage.getItem(SCENARIO_STORAGE_KEY)||'null'),meta)}catch{return defaultScenario(meta)}
}
function persistScenario({announce=true}={}){
 scenario=sanitizeScenario(scenario,meta);let stored=true;try{localStorage.setItem(SCENARIO_STORAGE_KEY,JSON.stringify(scenario))}catch{stored=false}
 const url=new URL(location.href);if(scenarioIsDefault(scenario,meta))url.searchParams.delete('scenario');else url.searchParams.set('scenario',scenarioParam(scenario,meta));
 history.replaceState(history.state,'',url.pathname+url.search+url.hash);renderScenario();summary();limit=40;render();
 if(announce||!stored)$('scenarioMessage').textContent=stored?'Senaryo yalnız bu tarayıcıda güncellendi; sistemin kayıtları değişmedi.':'Senaryo uygulandı, ama bu tarayıcı kaydetmeye izin vermiyor; sayfa yenilenince varsayılana döner.';
}
function scenarioCatalog(){return all.filter(r=>scenarioVisible(r,scenario))}
function isScenarioModified(){return !scenarioIsDefault(scenario,meta)}
const fieldTitles={price:'Fiyat',area:'Alan',unitPrice:'m² fiyatı',routeMax:'Mertur süresi',discountPct:'Emsale göre ucuzluk',officialType:'Tapu niteliği',neighborhood:'Mahalle'};
function fieldLabel(key){return fieldTitles[key]||meta.scenario?.customFields?.find(f=>f.key===key)?.label||key}
function ruleValue(field,value){return FIELD_TYPES[field]==='text'?String(value):field==='price'||field==='unitPrice'?money(value):field==='discountPct'?`%${num(value)}`:field==='routeMax'?`${num(value)} dk`:field==='area'?`${num(value)} m²`:num(value)}
function ruleLabel(rule){return `${fieldLabel(rule.field)} ${operatorLabels[rule.operator]||rule.operator} ${ruleValue(rule.field,rule.value)}`}
function updateRuleOperators(){
 const type=FIELD_TYPES[$('ruleField').value]||'number',operators=type==='number'?NUMBER_OPERATORS:TEXT_OPERATORS;
 $('ruleOperator').innerHTML=operators.map(value=>`<option value="${value}">${operatorLabels[value]}</option>`).join('');
 $('ruleValue').inputMode=type==='number'?'decimal':'text';$('ruleValue').placeholder=type==='number'?'Sayısal değer':'Tam eşleşen değer';
}
function scenarioTally(){const tally={fit:0,unknown:0,fail:0,out:0};for(const r of all)tally[scenarioEligibility(r,scenario).status]++;return tally}
function scoreRuleLines(){
 const active=all.filter(r=>r.lifecycle!=='excluded'),noValue=active.filter(r=>r.valueScore==null).length,noRoute=active.filter(r=>r.routeMax==null).length,penalties=new Map();
 for(const r of active){const line=(r.why||[]).map(String).find(w=>/sit: *-\d+ *puan/i.test(w));if(line){const key=line.replace(/\s+/g,' ').replace(/-(\d)/,'−$1').trim();penalties.set(key,(penalties.get(key)||0)+1)}}
 return [`Fiyat puanı ilanın emsal ilanlara göre ne kadar ucuz olduğundan, yakınlık puanı Mertur’a süreden gelir.`,
  `Fiyat puanı hesaplanamayan ilan ${SCORE_RULES.missingValue} sayılır (${num(noValue)} aday); Mertur süresi ölçülmemiş ilan ${SCORE_RULES.missingProximity} sayılır (${num(noRoute)} aday).`,
  `Emsali olmayan ilan en çok ${SCORE_RULES.noComparableCap} puan alabilir.`,
  penalties.size?`Sit cezası: ${[...penalties].map(([line,n])=>`${line} (${num(n)} aday)`).join(' · ')}.`:'Şu an sit cezası alan aday yok.',
  `Puan ${SCORE_RULES.min} ile ${SCORE_RULES.max} arasında tutulur.`]}
function ruleCounts(rule){const counts={fit:0,unknown:0,fail:0};for(const r of all){if(scenarioEligibility(r,scenario).officialBlock)continue;const result=customRuleResult(r,rule);counts[result===true?'fit':result===null?'unknown':'fail']++}return counts}
function renderScenario(){
 if(!scenario||!meta)return;const config=meta.scenario||{},modified=isScenarioModified(),tally=scenarioTally(),candidates=tally.fit+tally.unknown+tally.fail,visible=scenarioCatalog().length;
 $('scenarioState').textContent=modified?'Senaryo etkin':'Varsayılan';$('scenarioState').className=modified?'is-modified':'';
 $('scenarioCount').textContent=`${num(tally.fit)} / ${num(candidates)}`;
 $('scenarioTally').innerHTML=`<span class="tally-fit">${num(tally.fit)} uyuyor</span> <span class="tally-unknown">${num(tally.unknown)} bilinmiyor</span> <span class="tally-fail">${num(tally.fail)} kural dışı</span>`;
 $('hardGates').innerHTML=(config.gates||[]).map(g=>{const candidatesHit=all.filter(r=>r.lifecycle!=='excluded'&&r.scenarioFacts?.[g.key]===true).length,excludedHit=all.filter(r=>r.lifecycle==='excluded'&&(r.scenarioOfficialGateKeys||[]).includes(g.key)).length;return `<label class="gate-switch"><input type="checkbox" data-gate="${esc(g.key)}" ${scenario.gates[g.key]?'checked':''}><span><b>${esc(gateTitle(g.key))}</b><small>${num(candidatesHit)} aday · bu nedenle elenen ${num(excludedHit)} ilan</small></span></label>`}).join('');
 const total=scenario.weights.value+scenario.weights.proximity||1,proximityShare=Math.round(100*scenario.weights.proximity/total);
 $('balance').value=String(proximityShare);$('valueWeightOutput').value=`%${100-proximityShare}`;$('proximityWeightOutput').value=`%${proximityShare}`;
 $('scoreRules').innerHTML=scoreRuleLines().map(line=>`<li>${esc(line)}</li>`).join('');
 $('onlyEligible').checked=scenario.onlyEligible;
 $('customRuleList').innerHTML=scenario.custom.length?scenario.custom.map(rule=>{const n=ruleCounts(rule),label=ruleLabel(rule),include=rule.unknown!=='exclude';return `<span class="rule-chip"><span><b>${esc(label)}</b><small>${num(n.fit)} uyuyor · ${num(n.unknown)} bilinmiyor · ${num(n.fail)} uymuyor</small></span><button type="button" class="rule-unknown" data-toggle-unknown="${esc(rule.id)}" title="Değeri bilinmeyen ilanlar için seçimi değiştir">Bilinmeyen: ${include?'listede':'kural dışı'}</button><button type="button" class="rule-remove" data-remove-rule="${esc(rule.id)}" aria-label="${esc(label)} kuralını kaldır">×</button></span>`}).join(''):'<p class="explanation">Henüz kendi kuralın yok.</p>';
 $('scenarioMessage').textContent=`Listede ${num(visible)} ilan var; ${num(tally.fit)} aday senaryoya uyuyor${modified?' · sistemin kararları değişmedi':''}.`;
 $('gateNote').textContent=`Anahtar açıkken bu durumdaki ilanlar senaryoya girmez. Kapatırsan sistemin bu nedenle elediği ilanlar da senaryoya döner; sistemin kararı değişmez. Kendi kuralınla kabul edilen ${all.filter(r=>r.evidence?.yolKomşu==='verified_by_user_policy').length} yol (dere yolu, numarasız koridor) ve 1. derece doğal sit sınırındaki ${all.filter(r=>r.boundaryNote).length} parsel bu kurallara takılmaz; kartlarında ayrıca uyarı var.`;
}
function initScenario(){
 scenario=loadScenario();
 $('ruleField').innerHTML=(meta.scenario?.customFields||[]).map(field=>`<option value="${esc(field.key)}">${esc(fieldLabel(field.key))}</option>`).join('');updateRuleOperators();renderScenario();
 $('hardGates').onchange=e=>{const input=e.target.closest('[data-gate]');if(!input)return;scenario.gates[input.dataset.gate]=input.checked;persistScenario()};
 $('balance').oninput=e=>{const proximity=Number(e.target.value);scenario.weights={value:100-proximity,proximity};persistScenario({announce:false})};
 $('ruleField').onchange=updateRuleOperators;
 $('addRule').onclick=()=>{const field=$('ruleField').value,operator=$('ruleOperator').value,type=FIELD_TYPES[field],raw=$('ruleValue').value.trim(),value=type==='number'?Number(raw):raw;if(!raw||type==='number'&&!Number.isFinite(value)){$('scenarioMessage').textContent='Geçerli bir kural değeri gir.';return}scenario.custom.push({id:`r${Date.now().toString(36)}`,field,operator,value,unknown:$('ruleUnknown').value});$('ruleValue').value='';persistScenario()};
 $('customRuleList').onclick=e=>{const toggle=e.target.closest('[data-toggle-unknown]');if(toggle){const rule=scenario.custom.find(x=>x.id===toggle.dataset.toggleUnknown);if(rule){rule.unknown=rule.unknown==='exclude'?'include':'exclude';persistScenario()}return}const b=e.target.closest('[data-remove-rule]');if(!b)return;scenario.custom=scenario.custom.filter(rule=>rule.id!==b.dataset.removeRule);persistScenario()};
 $('onlyEligible').onchange=e=>{scenario.onlyEligible=e.target.checked;persistScenario()};
 $('resetScenario').onclick=()=>{scenario=defaultScenario(meta);try{localStorage.removeItem(SCENARIO_STORAGE_KEY)}catch{}persistScenario();$('scenarioPanel').open=false;$('scenarioMessage').textContent='Varsayılan politika geri yüklendi.'};
 $('copyScenario').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('scenario',scenarioParam(scenario,meta));try{await navigator.clipboard.writeText(url.href);$('scenarioMessage').textContent='Paylaşılabilir senaryo bağlantısı kopyalandı.'}catch{$('scenarioMessage').textContent='Bağlantı kopyalanamadı; adres çubuğundaki URL kullanılabilir.'}};
}
// B9: one count definition, from scanned to candidate; B6: the 1–3 things that hold the research up.
function flowStep(key,n,label,sub,extra=''){return `<button class="flow-step ${extra}" data-summary="${key}" data-label="${esc(`${num(n)} ${label}`)}"><b>${num(n)}</b><span>${esc(label)}</span>${sub?`<small>${esc(sub)}</small>`:''}</button>`}
function focusItems(){
 const status=meta.status||{},messaging=status.sellerMessaging||{},active=all.filter(r=>r.lifecycle!=='excluded'),items=[],sahibinden=active.filter(r=>/sahibinden/i.test(r.nextStep||''));
 if(messaging.blocked)items.push({key:'sahibinden',contains:true,tone:'blocked',title:`Sahibinden mesaj engeli: ${num(messaging.prepared||0)} mesaj taslağı gönderilemiyor`,sub:`${num(sahibinden.length)} aday bu engeli bekliyor · engel: ${messaging.blocker||'kayıtlı değil'} · son başarılı gönderim ${shortDate(messaging.lastSuccessfulAt)||'—'} · son kontrol ${shortDate(messaging.lastCheckedAt)||'—'}`});
 const groups=new Map();for(const r of active){const step=String(r.nextStep||'');if(!step||r.funnelStage==='complete'||/sahibinden/i.test(step))continue;const g=groups.get(step)||{n:0,stages:new Set()};g.n++;g.stages.add(r.funnelStage);groups.set(step,g)}
 const lower=x=>/^Mertur/.test(x)?x:x.charAt(0).toLocaleLowerCase('tr')+x.slice(1);
 for(const [step,g] of [...groups].sort((a,b)=>b[1].n-a[1].n).slice(0,3-items.length)){const missing=step.startsWith('Eksik: ')?step.slice(7).split(/,\s*/):null;items.push({key:step,title:missing?(missing.length===1?`${num(g.n)} adayda yalnız ${lower(missing[0])} eksik`:`${num(g.n)} adayda eksik: ${missing.map(lower).join(', ')}`):`${num(g.n)} aday: ${step}`,sub:`${g.stages.size===1?`Aşama: ${stageLabels[[...g.stages][0]]||[...g.stages][0]} · `:''}listelemek için dokun`})}
 return items;
}
function summary(){const s=meta.status,f=s.funnel,excluded=all.filter(r=>r.lifecycle==='excluded'),hidden=excluded.filter(r=>r.defaultVisible===false).length,candidates=all.length-excluded.length,shortlist=all.filter(r=>feedback.get(String(r.id))?.decision==='shortlist').length;
 $('summary').innerHTML=flowStep('all',all.length,'ilan tarandı','')+'<span class="flow-arrow" aria-hidden="true">→</span>'+flowStep('excluded',excluded.length,'elendi',hidden?`${num(hidden)} tanesi sit nedeniyle listede gizli`:'','is-excluded')+'<span class="flow-arrow" aria-hidden="true">→</span>'+flowStep('active',candidates,'aday','','is-candidate')
  +`<div class="flow-sub" aria-label="Adayların durumu">${[['technical',f.technicallyComplete,'teknik kontrolü tamam'],['positive',f.positive,'koşullu olumlu'],['shortlist',shortlist,'kısa listende']].map(([key,n,label])=>`<button data-summary="${key}" data-label="${esc(`${num(n)} ${label}`)}"><b>${num(n)}</b> ${esc(label)}</button>`).join('')}</div>`;
 const counts=new Map();for(const r of excluded)for(const key of exclusionCategories(r))counts.set(key,(counts.get(key)||0)+1);
 $('exclusionSummary').textContent=`${num(excluded.length)} ilan neden elendi?`;
 $('exclusionReasonList').innerHTML=EXCLUSION_GROUPS.filter(([key])=>counts.get(key)).sort((a,b)=>counts.get(b[0])-counts.get(a[0])).map(([key,label])=>`<button data-reason="${esc(key)}" data-label="${esc(`Elendi · ${label}`)}"><b>${num(counts.get(key))}</b> ${esc(label)}</button>`).join('');
 const items=focusItems();$('blockers').innerHTML=items.length?items.map(item=>`<li class="${item.tone?`is-${item.tone}`:''}"><button data-next="${esc(item.key)}" data-contains="${item.contains?'1':''}" data-label="${esc(item.title)}"><b>${esc(item.title)}</b><small>${esc(item.sub)}</small></button></li>`).join(''):'<li class="muted">Şu an bekleyen ortak bir iş görünmüyor.</li>';
 }
// The research status panel does not depend on decisions or the scenario; it is drawn once per load so open lists stay open.
function progress(){const s=meta.status,f=s.funnel,excluded=all.filter(r=>r.lifecycle==='excluded'),hidden=excluded.filter(r=>r.defaultVisible===false).length,candidates=all.length-excluded.length;
 $('funnel').innerHTML=f.stages.map((s,i)=>`<article class="stage"><div class="stage-head"><span class="stage-index">${i+1}</span><h3>${esc(s.label)}</h3></div><div class="stage-numbers">${[['entered','Ulaştı'],['passed','Geçti'],['blocked','Bekliyor']].map(([k,l])=>`<button class="${k==='blocked'?'waiting':''}" data-stage="${s.key}" data-membership="${k}" ${s[k]?'':'disabled'} aria-label="${esc(s.label)}: ${s[k]} ${l.toLowerCase()}"><b>${s[k]}</b><span>${l}</span></button>`).join('')}</div><details><summary>Kök nedenler · ${s.blocked}</summary>${s.reasons.length?s.reasons.map(r=>`<details class="reason reason-row" data-reason-stage="${esc(s.key)}" data-reason-label="${esc(r.label)}"><summary><strong>${r.count}</strong> · ${esc(r.label)}<small>Son hareket: ${date(r.lastAt)} · ilanları görmek için dokun</small></summary><div class="reason-links"></div></details>`).join(''):'<p>Bu kapıda bekleyen ilan yok.</p>'}</details><p class="muted">Son hareket: ${date(s.lastAt)}</p></article>`).join('');
 $('parallel').innerHTML=f.parallelChecks.map(p=>`<article class="check-card"><strong>${esc(p.label)}</strong><div class="parallel-counts"><button data-parallel="${p.key}" data-membership="entered" ${p.eligible?'':'disabled'} aria-label="${esc(p.label)}: ${p.eligible} ulaştı">${p.eligible} ulaştı</button><button data-parallel="${p.key}" data-membership="passed" ${p.done?'':'disabled'} aria-label="${esc(p.label)}: ${p.done} geçti">${p.done} geçti</button></div><progress max="${p.eligible||1}" value="${p.done}" aria-label="${esc(p.label)} tamamlanma"></progress><button data-parallel="${p.key}" data-membership="pending" ${p.pending?'':'disabled'} aria-label="${esc(p.label)}: ${p.pending} bekliyor">${p.pending} bekliyor →</button><p><small>${Object.entries(p.grades||{}).map(([k,n])=>`${n} ${gradeLabel(p.key,k)}`).join(' · ')}</small></p><details><summary>Kök neden ve son hareket</summary>${(p.reasons||[]).map(r=>`<p class="reason"><strong>${r.count}</strong> · ${esc(r.label)}<br><small>${date(r.lastAt)}</small></p>`).join('')||'<p>Bu kriterde bekleyen ilan yok.</p>'}<small>Son hareket: ${date(p.lastAt)}</small></details></article>`).join('');
 $('scope').textContent=`${num(all.length)} ilan tarandı · ${num(excluded.length)} elendi (${num(hidden)} tanesi kesin sit elemesi nedeniyle listede gizli; senaryoda ilgili kural kapatılınca görünür) · ${num(candidates)} aday. ${num(f.reviewed)} adayda final sonuçlandı. Kaynak: ${meta.source||'—'} · üretim ${date(meta.generatedAt)}.`;$('method').textContent=meta.method?.note||'';
}
function matchesSelection(r){if(!selection)return true;const {type,key,member}=selection;if(type==='stage')return member==='blocked'?r.funnelStage===key:(r[member==='entered'?'funnelReached':'funnelPassed']||[]).includes(key);if(type==='parallel'){const reached=(r.funnelPassed||[]).includes('officialParcel'),missing=(r.parallelMissing||[]).includes(key);return reached&&(member==='entered'||(member==='passed'&&!missing)||(member==='pending'&&missing))}if(type==='summary')return key==='all'||(key==='active'?r.lifecycle!=='excluded':key==='excluded'?r.lifecycle==='excluded':key==='technical'?r.technicalComplete:key==='shortlist'?feedback.get(String(r.id))?.decision==='shortlist':r.recommended);if(type==='reason')return exclusionCategories(r).includes(key);if(type==='next')return r.lifecycle!=='excluded'&&(!selection.stage||r.funnelStage===selection.stage)&&(selection.contains?new RegExp(key,'i').test(r.nextStep||''):r.nextStep===key);return true}
function useTypeValues(){return [...selectedUseTypes].sort((a,b)=>a.localeCompare(b,'tr'))}
function updateUseTypeUi({url=true}={}){
 const values=useTypeValues();$('useTypeSummary').textContent=values.length===0?'Tümü':values.length===1?values[0]:`${values.length} nitelik seçili`;
 $('useTypeFilter').classList.toggle('has-selection',values.length>0);
 if(url){const next=new URL(location.href);if(values.length)next.searchParams.set('types',values.join(','));else next.searchParams.delete('types');history.replaceState(history.state,'',next.pathname+next.search+next.hash)}
}
function initUseTypes(records){
 const values=[...new Set(records.map(r=>r.officialType).filter(x=>x&&x!=='—'))].sort((a,b)=>a.localeCompare(b,'tr')),requested=new Set((new URL(location.href).searchParams.get('types')||'').split(',').map(x=>x.trim()).filter(Boolean));
 selectedUseTypes=new Set(values.filter(value=>requested.has(value)));
 $('useTypeOptions').innerHTML=values.map(value=>`<label><input type="checkbox" value="${esc(value)}" ${selectedUseTypes.has(value)?'checked':''}><span>${esc(value)}</span></label>`).join('')||'<p class="muted">Nitelik kaydı yok.</p>';
 updateUseTypeUi({url:requested.size>0&&selectedUseTypes.size!==requested.size});
}
function filtered(){const v=Object.fromEntries(filterIds.map(k=>[k,$(k).value])),q=v.search.trim().toLocaleLowerCase('tr');const showHidden=selection&&(selection.type==='reason'||selection.type==='summary'&&(selection.key==='all'||selection.key==='excluded'));return all.filter(r=>{if(!showHidden&&!scenarioVisible(r,scenario))return false;const f=feedback.get(String(r.id));if(!matchesSelection(r))return false;if(q&&!`${r.id} ${r.title} ${r.neighborhood} ${r.parcel} ${r.officialType}`.toLocaleLowerCase('tr').includes(q))return false;if(v.neighborhood&&r.neighborhood!==v.neighborhood)return false;if(selectedUseTypes.size&&!selectedUseTypes.has(r.officialType))return false;if(v.stage&&r.funnelStage!==v.stage)return false;if(v.decision&&(v.decision==='noted'?!f?.note:v.decision==='undecided'?!!f?.decision:f?.decision!==v.decision))return false;if(v.missing&&!(r.parallelMissing||[]).includes(v.missing))return false;if(v.verification&&(v.verification==='edge'?!r.boundaryNote:v.verification==='technical'?!r.technicalComplete:v.verification==='positive'?!r.recommended:!Object.values(r.evidenceGrades||{}).includes(v.verification)))return false;
 for(const [key,x,lower] of [['minPrice',r.price,true],['maxPrice',r.price,false],['minArea',area(r),true],['maxArea',area(r),false]])if(v[key]!==''&&(x==null||(lower?x<Number(v[key]):x>Number(v[key]))))return false;return true}).sort((a,b)=>{if($('sort').value==='rank'&&isScenarioModified()){const order={fit:0,unknown:1,fail:2,out:3},statusOrder=order[scenarioEligibility(a,scenario).status]-order[scenarioEligibility(b,scenario).status];if(statusOrder)return statusOrder;const scoreOrder=scenarioScore(b,scenario)-scenarioScore(a,scenario);if(scoreOrder)return scoreOrder}const exclusionOrder=Number(a.lifecycle==='excluded')-Number(b.lifecycle==='excluded');if(exclusionOrder)return exclusionOrder;switch($('sort').value){case 'price':return (a.price??Infinity)-(b.price??Infinity);case 'unit':return (areaFacts(a).unit??Infinity)-(areaFacts(b).unit??Infinity);case 'discount':return (b.comparison?.discountPct??-Infinity)-(a.comparison?.discountPct??-Infinity);case 'area':return (area(b)??-Infinity)-(area(a)??-Infinity);case 'route':return (a.routeMax??Infinity)-(b.routeMax??Infinity);case 'recent':return String(b.lastActivityAt||'').localeCompare(a.lastActivityAt||'');default:return a.rank-b.rank}})}
// A8: a share sale lists the sold share and the whole parcel separately; m² price follows the share.
function areaFacts(r){const listing=r.listingArea,official=r.officialArea,shared=r.ownershipScreen?.status==='shared';if(shared&&listing!=null)return {label:'Satılan pay',value:`${num(listing)} m²`,note:official!=null?`parselin tamamı ${num(official)} m²`:'',unit:r.price!=null&&listing?r.price/listing:null,unitNote:'paya göre'};if(listing!=null&&official!=null&&Math.abs(official-listing)/Math.max(listing,1)>.15)return {label:'Alan',value:`${num(official)} m²`,note:`tapuda; ilanda ${num(listing)} m²`,unit:r.unitPrice,unitNote:''};return {label:'Toplam alan',value:`${num(official??listing)} m²`,note:'',unit:r.unitPrice,unitNote:''}}
// C1/C2: why a candidate is outside the scenario, or which rule could not be checked.
function ruleIssues(r,state){const issues=[];for(const key of state.failedGates)issues.push(key==='underMinimumArea'?`${gateTitle(key)} · ${num(area(r))} m²`:key==='overBudget'?`${gateTitle(key)} · ${money(r.price)}`:gateTitle(key));for(const rule of state.failedRules){const v=fieldValue(r,rule.field);issues.push(v==null||v===''?`${fieldLabel(rule.field)} bilinmiyor · kuralın bilinmeyenleri dışarıda bırakıyor`:`${ruleLabel(rule)} kuralına uymuyor · bu ilanda ${ruleValue(rule.field,v)}`)}return {fail:issues,unknown:state.unknownRules.map(rule=>`${fieldLabel(rule.field)} bilinmiyor · kural: ${operatorLabels[rule.operator]||rule.operator} ${ruleValue(rule.field,rule.value)}`)}}
function ruleBanner(r,state){if(state.status!=='fail'&&state.status!=='unknown')return '';const issues=ruleIssues(r,state);return `${issues.fail.length?`<p class="rule-banner is-fail"><b>KURAL DIŞI</b><span>${esc(issues.fail.join(' · '))}</span></p>`:''}${issues.unknown.length?`<p class="rule-banner is-unknown"><b>BİLİNMİYOR</b><span>${esc(issues.unknown.join(' · '))} · listede tutuluyor</span></p>`:''}`}
// B10: on a phone the card shows one price line and one location line; the full blocks stay on wider screens and in the detail.
function comparisonShort(r){const d=r.comparison?.discountPct;return d==null?'emsal yok':Math.abs(d)<5?'emsaline yakın':d>0?`emsalden %${num(d)} ucuz`:`emsalden %${num(-d)} pahalı`}
function cardCompact(r,a){return `<p class="card-compact"><b>${money(r.price)}</b> · ${esc(a.value)}${a.unit!=null?` · ${money(a.unit)}/m²`:''}<br><span>Mertur ${esc(routeShort(r))} · ${esc(comparisonShort(r))}</span></p>`}
function card(r){
 const f=feedback.get(String(r.id)),excluded=r.lifecycle==='excluded',state=scenarioEligibility(r,scenario),modified=isScenarioModified(),scenarioValue=scenarioScore(r,scenario),relaxed=excluded&&state.relaxed.length;
 const scenarioNotice=relaxed?`Senaryo: ${state.relaxed.map(key=>gateLabels[key]).join(', ')} kuralı kapalı; sistemin kararı değişmedi.`:'';
 const tone=excluded?'':sitTone(r),shared=r.ownershipScreen?.status==='shared',a=areaFacts(r),risk=excluded?'':riskText(r);
 const score=modified&&state.eligible?`<b>Senaryo ${num(scenarioValue)}</b><small>Sistem ${num(r.score)}</small>`:excluded?'Puan dışı':modified?`Sistem ${num(r.score)}`:`Puan ${num(r.score)}`;
 return `<article class="listing${excluded?' is-excluded':''}${relaxed?' is-scenario-revealed':''}${tone?` sit-${tone}`:''}" data-id="${esc(r.id)}" aria-label="${excluded?'Elendi · ':''}${esc(r.neighborhood)} ${esc(r.parcel)} · ${esc(readableTitle(r.title))}">${excluded?`<p class="exclusion-banner"><b>ELENDİ</b><span>${esc(exclusionText(r))}</span></p>`:''}${scenarioNotice?`<p class="scenario-banner"><b>SENARYO</b><span>${esc(scenarioNotice)}</span></p>`:''}${ruleBanner(r,state)}<div class="listing-core"><div class="listing-identity"><h3>${esc(readableTitle(r.title))}</h3><div class="listing-subline"><p class="listing-location"><strong>${esc(r.neighborhood)}</strong> · ${esc(r.parcel)}</p><div class="listing-kicker"><span>#${esc(r.id)}</span>${statusBadge(r)}${statusKey(r)==='active'&&stageLabels[r.funnelStage]?badge(stageLabels[r.funnelStage]):''}${shared?badge('Hisseli','conflict'):''}${decisionLabel(f)?badge(decisionLabel(f),'provisional'):''}<span class="listing-score" title="${excluded?'Sistemin eleme kararı puandan önce uygulanır':'Sistem puanı: fiyat avantajı ve Mertur yakınlığı; uygunluk kararı değildir'}">${score}</span></div></div></div>${cardCompact(r,a)}<div class="listing-facts"><div class="finance"><div class="finance-price"><span>Fiyat</span><strong>${money(r.price)}</strong></div><div><span>${esc(a.label)}</span><strong>${esc(a.value)}</strong>${a.note?`<small>${esc(a.note)}</small>`:''}</div><div><span>m² fiyatı${a.unitNote?` (${esc(a.unitNote)})`:''}</span><strong>${a.unit==null?'Belirsiz':money(a.unit)}</strong></div><div><span>Tapu niteliği</span><strong>${esc(r.officialType)}</strong></div></div><div class="listing-travel"><span class="section-label">Mertur</span>${routeCard(r)}<p class="comparison-label">${esc(r.comparison?.label||'Yeterli aynı nitelikte emsal yok')}${r.comparison?.median!=null?`<small>${esc(r.comparison.type)} · N=${r.comparison.count} · ${esc(r.comparison.confidence)}</small>`:''}</p></div>${cardMedia(r)}</div></div>${criteria(r)}${risk?`<p class="risk-note"><span>Risk</span>${esc(risk)}</p>`:''}<div class="next"><span><b>${excluded?'Durum':'Sıradaki'}:</b> ${esc(excluded?'Sistem eledi; sıralamada yer almaz.':r.nextStep)}</span><div class="listing-actions"><button class="detail-open" aria-label="${esc(readableTitle(r.title))} ilanının kanıt ve detaylarını aç">Kanıt ve detay</button>${link(r.listingUrl,'Sahibinden’de aç')}${link(r.parcelUrl,'TKGM’de aç','wide-only')}</div></div></article>`;
}
function comparisonDetail(r){const c=r.comparison||{};return `<section class="detail-section"><h3>Emsal fiyat karşılaştırması</h3><p>${esc(c.label||'Yeterli emsal yok')}</p><dl class="facts">${fact('Karşılaştırma grubu',`${c.type||'Nitelik belirsiz'} · ${c.scope||'Grup yok'}`)}${fact('Alan bandı',c.areaMin==null?'Belirsiz':`${num(c.areaMin)}–${num(c.areaMax)} m²`)}${fact('Medyan m² fiyatı',c.median==null?'Yeterli emsal yok':money(c.median))}${fact('Bu ilanın m² fiyatı',r.unitPrice==null?'Belirsiz':money(r.unitPrice))}${fact('Diğer emsal sayısı',c.count??'—')}${fact('Güven sınırı',c.confidence||'Yetersiz')}</dl><p class="dialog-note">Fark = 100 × (medyan − ilan m² fiyatı) / medyan. Aynı tapu niteliği, 0,5–2 kat alan; mahallede en az 5, yoksa Datça genelinde en az 8 farklı parsel. Aynı parselin kopyaları tek emsal; bu parsel dışarıda. Medyan tekil uç fiyatlara dayanıklıdır; %5 altı fark emsaline yakın sayılır. İlan fiyatıdır, gerçekleşmiş satış veya ekspertiz değildir. Yeni gösterge puanı ve sıralamayı değiştirmez; mevcut puanın eski emsal bileşeni ayrıdır.</p></section>`}

function syncFacetButtons(){document.querySelectorAll('[data-stage],[data-parallel],[data-summary],[data-reason],[data-next]').forEach(button=>{const same=selection&&((selection.type==='stage'&&button.dataset.stage===selection.key)||(selection.type==='parallel'&&button.dataset.parallel===selection.key)||(selection.type==='summary'&&button.dataset.summary===selection.key)||(selection.type==='reason'&&button.dataset.reason===selection.key)||(selection.type==='next'&&button.dataset.next===selection.key))&&(!selection.member||button.dataset.membership===selection.member);button.setAttribute('aria-pressed',String(!!same))})}
