function resetFilters({history=true}={}){filterIds.forEach(k=>$(k).value='');selectedUseTypes.clear();$('useTypeOptions').querySelectorAll('input').forEach(input=>input.checked=false);updateUseTypeUi();selection=null;limit=40;if(history)window.history.pushState({facet:null},'',location.pathname+location.search+'#listings');render()}
