$('funnel').addEventListener('click',e=>{const detail=e.target.closest('[data-open-detail]');if(detail){openDetail(detail.dataset.openDetail);return}const show=e.target.closest('.reason-show');if(show){const row=show.closest('.reason-row');select({type:'next',key:row.dataset.reasonLabel,stage:row.dataset.reasonStage,label:`${stageLabels[row.dataset.reasonStage]} · ${row.dataset.reasonLabel}`})}});
